<script setup>
import {ref,onMounted} from 'vue';
import BotCheck from './BotCheck.vue';
import {submitConsumerManagement} from '../services/consumerManagement';
const kind=ref('baja'),email=ref(''),reference=ref(''),message=ref(''),token=ref(''),busy=ref(false),error=ref(''),receipt=ref(''),bot=ref(null);
const requestId=crypto.randomUUID();
onMounted(()=>{if(window.location.hash==='#arrepentimiento')kind.value='arrepentimiento';});
async function submit(){if(busy.value || !token.value)return;busy.value=true;error.value='';try{const result=await submitConsumerManagement({kind:kind.value,email:email.value.trim(),reference:reference.value.trim(),message:message.value.trim(),token:token.value,requestId});receipt.value=result.receipt;}catch{error.value='No pudimos registrar la solicitud. Volvé a verificar o escribí a meq1985@hotmail.com.';token.value='';bot.value?.reset?.();}finally{busy.value=false;}}
function download(){const text=`Electricista Xpress\nSolicitud recibida: ${receipt.value}\nTipo: ${kind.value}\nCorreo: ${email.value}\nEl comprobante acredita recepción; no confirma baja ni devolución completada.\nContacto: meq1985@hotmail.com`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='comprobante-gestion.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
</script>
<template><section id="baja" class="consumer-form" aria-label="Solicitud de baja o arrepentimiento"><template v-if="receipt"><h2>Solicitud recibida</h2><p role="status">Tu código de identificación es <strong>{{receipt}}</strong>.</p><p>Conservá este comprobante. Se registró la solicitud; esto no confirma una baja o devolución ya completada. Revisaremos los datos por el correo indicado para gestionar lo que corresponda.</p><button type="button" @click="download">Descargar comprobante</button></template><form v-else @submit.prevent="submit"><h2 id="arrepentimiento">Registrar una solicitud</h2><label>Tipo de solicitud<select v-model="kind" :disabled="busy"><option value="baja">Baja de la suscripción</option><option value="arrepentimiento">Arrepentimiento de la contratación</option></select></label><label>Correo de la cuenta<input v-model="email" type="email" required maxlength="254" autocomplete="email" :disabled="busy" /></label><label>Referencia de contratación, si la tenés<input v-model="reference" maxlength="100" :disabled="busy" /></label><label>Información adicional, opcional<textarea v-model="message" maxlength="500" :disabled="busy" /></label><p>No envíes contraseñas, códigos de acceso, tarjetas ni documentos. No necesitás iniciar sesión. Los datos se usan para atender esta solicitud; consultá la <RouterLink to="/privacidad">política de privacidad</RouterLink>.</p><BotCheck ref="bot" action="consumer_request" @verified="token=$event"/><p v-if="error" role="alert">{{error}}</p><button type="submit" :disabled="busy || !token">{{busy?'Registrando…':'Enviar solicitud y obtener comprobante'}}</button></form></section></template>
<style scoped>.consumer-form{margin:24px 0;padding:22px;border:1px solid #536779;border-radius:12px}.consumer-form label{display:flex;flex-direction:column;gap:6px;margin:14px 0}.consumer-form input,.consumer-form select,.consumer-form textarea{font:inherit;padding:10px;background:#162431;color:#edf2f8;border:1px solid #647789;border-radius:6px}.consumer-form button{padding:12px;background:#99d2ff;border:0;border-radius:6px;font-weight:bold}.consumer-form button:disabled{opacity:.5}.consumer-form strong{overflow-wrap:anywhere}</style>
